export interface RagSettings {
  enabled?: boolean;
  topK?: number;
  embeddings?: EmbeddingsSettings;
  /** If true, select RAG context via k-medoids over a larger candidate set. */
  useKMedoids?: boolean;
  /** Candidate count to retrieve before k-medoids (must be >= topK). */
  candidateCount?: number;
  /** Text extractor used by the RAG indexer (default: native). */
  extractor?: "native" | "sqlite-rag";
  /** Python command used when extractor is sqlite-rag (default: auto-detect). */
  python?: string;
}

update_md5_52bf3c917cb6448975060386b30b2.content_md5_52bf3c917cb6448975060386b30b:
export interface RagSettings {
  enabled?: boolean;
  topK?: number;
  embeddings?: EmbeddingsSettings;
  /** If true, select RAG context via k-medoids over a larger candidate set. */
  useKMedoids?: boolean;
  /** Candidate count to retrieve before k-medoids (must be >= topK). */
  candidateCount?: number;
  /** Text extractor used by the RAG indexer (default: native). */
  extractor?: "native" | "sqlite-rag";
  /** Python command used when extractor is sqlite-rag (default: auto-detect). */
  python?: string;
  /** If true, search chat history before project files in hybrid retrieval (default: true). */
  searchChatFirst?: boolean;
  /** Path prefix for chat entries in the vector DB (default: "chat://"). */
  chatPrefix?: string;
}

